"mainEntity": [
{
"@type": "Question",
"name": "Which cities do you actually work in?",
"acceptedAnswer": {
"@type": "Answer",
"text": "Boca Raton, Delray Beach, Boynton Beach, Lake Worth Beach, West Palm Beach, and Palm Beach, plus the surrounding communities in between. We keep the territory tight on purpose so our crew spends the day on your job rather than in traffic."
}
},
{
"@type": "Question",
"name": "Does the permit process change depending on which city I am in?",
"acceptedAnswer": {
"@type": "Answer",
"text": "Yes, and it is the part clients are most often surprised by. Each municipality runs its own building department with its own portal and review process. Boca Raton, for instance, uses Boca eHub for applications and inspections and Boca ePlans for plan review. We confirm the path for your address before committing to a schedule."
}
},
{
"@type": "Question",
"name": "Do you handle the permits and the paperwork?",
"acceptedAnswer": {
"@type": "Answer",
"text": "Yes. We handle the permitting process: preparing the submission, managing the permits and sub permits, recording the Notice of Commencement with the legal description, street address, and tax folio number that Florida Statute 713.13 requires, and carrying the project through inspections."
}
},
{
"@type": "Question",
"name": "My community has an HOA or a condo board. Is that a problem?",
"acceptedAnswer": {
"@type": "Answer",
"text": "No, it is normal here and we plan around it. We prepare the scope documentation, supply insurance certificates naming the association, and work within the building's rules on work hours, elevator use, and debris removal. Because boards meet on their own schedule, we build the approval window into the timeline from the start."
}
},
{
"@type": "Question",
"name": "What kind of projects do you take?",
"acceptedAnswer": {
"@type": "Answer",
"text": "Full-scope residential remodeling: kitchens, bathrooms, whole-home renovations, custom closets, and built-in cabinetry. We do not take small-repair, maintenance, or urgent-repair work. If a project is smaller than that, we are happy to point you somewhere better suited to it."
}
},
{
"@type": "Question",
"name": "Are you insured?",
"acceptedAnswer": {
"@type": "Answer",
"text": "Yes, fully insured in Florida. Documentation is available before work begins, and we provide it directly to your association or property manager when required."
}
}
]
}
]
